sql-service.query:
BEGIN
DECLARE @t_device_gu varchar(4) DECLARE @o_mib_id varchar(10) DECLARE @t_mib_id varchar(10) DECLARE @m_Done INT
DECLARE O_MIB CURSOR FOR SELECT A.MIB_ID FROM MS_MIB A WHERE A.DEVICE_ID = ?O_DEVICE_ID
SELECT DEVICE_GU1 INTO t_device_gu FROM MS_DEVICE WHERE DEVICE_ID = ?T_DEVICE_ID;
OPEN O_MIB;
REPEAT FETCH NEXT FROM O_MIB INTO o_mib_id;
IF NOT m_Done THEN
SELECT CONCAT(t_device_gu, LPAD(IFNULL(MAX(CAST(SUBSTR(A.MIB_ID, 4) AS UNSIGNED)), 0) + 1, 4, 0)) INTO t_mib_id FROM MS_MIB A WHERE A.MIB_ID LIKE CONCAT(t_device_gu, '%');
INSERT INTO MS_MIB ( MIB_ID , DEVICE_ID , OID_TYPE , OID_GROUP , OID_DESC , SCH_INTERVL , SCH_TIME , USE_YN ) SELECT t_mib_id , ?T_DEVICE_ID AS DEVICE_ID , B.OID_TYPE , B.OID_GROUP , B.OID_DESC , B.SCH_INTERVL , B.SCH_TIME , B.USE_YN FROM MS_MIB B WHERE B.MIB_ID = o_mib_id;
INSERT INTO MS_OID ( MIB_ID , OID_NAME , SEQ , OID , OID_DESC ) SELECT t_mib_id AS MIB_ID , B.OID_NAME , B.SEQ , B.OID , B.OID_DESC FROM MS_OID B WHERE B.MIB_ID = o_mib_id;
END IF; UNTIL m_Done END REPEAT;
CLOSE O_MIB;
COMMIT;
END;
